cd /workspace/devtests && python3 - <<'EOF'
import sys, json, random, subprocess
sys.path.insert(0,'/workspace/devtests')
from qlib import *
random.seed(7)
PKT_KEYS = {'packets','datagrams','closed','keys','received','key_epoch','epochs','opened','used',
            'send_max_data','send_max_streams','streams','crypto','acknowledged','peer_cids',
            'retire_prior_to','retired_local'}
PKT_ROW = {'event','packet','offset','level','pn','epoch','status','sha256'}
DG_ROW = {'event','packets','accepted','bytes','sha256'}
bad = 0
for trial in range(40):
    n = random.randint(1,6)
    events=[]
    for i in range(n):
        if random.random()<0.3:
            events.append(keys(*random.sample(['I','H','A'], random.randint(1,3))))
        else:
            ln = random.randint(0,40)
            wire = bytes(random.getrandbits(8) for _ in range(ln))
            auth = [random.choice([None, random.randint(0,3)]) for _ in range(random.randint(0,4))]
            events.append(dg(wire, auth))
    t = trace(events)
    payload=json.dumps({'traces':[t]})
    p=subprocess.run([sys.executable,'/workspace/run.py','/workspace/tmp/classes'],input=payload.encode(),capture_output=True)
    if p.returncode!=0:
        print('CRASH', p.stderr.decode()[:2000]); bad+=1; continue
    try:
        r=json.loads(p.stdout)
    except Exception as e:
        print('BADJSON', e, p.stdout[:200]); bad+=1; continue
    tr=r['traces'][0]
    if set(tr.keys())!=PKT_KEYS: print('KEYS', set(tr.keys())^PKT_KEYS); bad+=1
    for row in tr['packets']:
        if set(row.keys())!=PKT_ROW: print('PROW', row); bad+=1
    for row in tr['datagrams']:
        if set(row.keys())!=DG_ROW: print('DROW', row); bad+=1
    if tr['closed'] is not None and set(tr['closed'].keys())!={'event','packet','offset','code'}:
        print('CROW', tr['closed']); bad+=1
print('fuzz done, problems:', bad)
EOF
